import{_ as a,o as i,c as t,a2 as n}from"./chunks/framework.CDpkVv68.js";const u=JSON.parse('{"title":"Familiarity compartida y entrenamiento","description":"","frontmatter":{},"headers":[],"relativePath":"es/game-design/characters/familiarity.md","filePath":"es/game-design/characters/familiarity.md"}'),r={name:"es/game-design/characters/familiarity.md"};function o(s,e,d,c,l,m){return i(),t("div",null,[...e[0]||(e[0]=[n('<h1 id="shared-familiarity-and-training" tabindex="-1">Familiarity compartida y entrenamiento <a class="header-anchor" href="#shared-familiarity-and-training" aria-label="Enlace permanente a &quot;Familiarity compartida y entrenamiento&quot;">​</a></h1><p><strong>Estado del diseño: Propuesto.</strong> Los ejemplos numéricos son hipótesis de prototipo, no equilibrio definitivo. <strong>Implementación/disponibilidad:</strong> no establecida para estas mecánicas. <strong>Verificación:</strong> revisión documental, sin prototipo jugable. <strong>Revisión:</strong> 2026-10-09, Batch 05.</p><p><a href="/Syrolands-Public/es/guide/characters/familiarity.html">Guía del jugador</a> · <a href="/Syrolands-Public/es/game-design/combat/overview.html">Fundamentos de combate</a> · <a href="/Syrolands-Public/es/game-design/combat/variable-registry.html">Registro de variables de combate</a></p><h2 id="one-fluency-vocabulary" tabindex="-1">Un vocabulario de fluidez <a class="header-anchor" href="#one-fluency-vocabulary" aria-label="Enlace permanente a &quot;Un vocabulario de fluidez&quot;">​</a></h2><p><strong>Skill → Technique → Familiarity → Prepared Repertoire → Player Execution</strong> separa capacidad general, aprendizaje permanente, ejecución practicada, opciones listas y aplicación temporal. Para hechizos, Active Memory es el sistema de preparación relacionado, no una afirmación de que las ranuras marciales y la memoria de hechizos compartan fórmulas de capacidad.</p><p>Batch 05 propone tres estados compartidos para Familiarity de SA y patrones de hechizos: <strong>Learned, Practiced, Mastered</strong>. Esto sustituye las etiquetas ilustrativas de Batch 04 «recién aprendido / familiar / muy familiar / profundamente interiorizado» como vocabulario propuesto actual; no eleva una escala a equilibrio con estado Aceptado. La Mastery más amplia de disciplina/afinidad y el dominio de habilidad principal a 100 siguen siendo conceptos separados.</p><table tabindex="0"><thead><tr><th>Estado</th><th>Calidad de ejecución con estado Propuesto</th><th>Qué permanece</th></tr></thead><tbody><tr><td>Learned</td><td>Mayor coste de stamina, peor recuperación, menor consistencia/precisión, señales más obvias y ventanas de respuesta más estrechas cuando corresponda</td><td>La técnica se conoce; siguen aplicándose condiciones de validez/preparación</td></tr><tr><td>Practiced</td><td>Ejecución estándar/base</td><td>El conocimiento sigue siendo permanente</td></tr><tr><td>Mastered</td><td>Eficiencia algo mejor de stamina/recuperación, consistencia, tiempos más tolerantes y señales/control refinados</td><td>Sin enorme bonificación de daño bruto ni éxito universal</td></tr></tbody></table><p>Los efectos son candidatos específicos de cada acción, no penalizaciones obligatorias para todo hechizo. Los efectos sobre recursos/referencia/Concentration de hechizos siguen en magia; Familiarity no consume skillcap adicional. La adquisición es permanente: la fluidez puede pasar de <strong>Mastered → Practiced → Learned</strong>, nunca volver a Unknown por decaimiento. El acceso básico no desaparece aleatoriamente por practicar poco. Olvido/respecialización por elección queda fuera de esta propuesta de decaimiento.</p><h2 id="maintenance-without-absence-punishment" tabindex="-1">Mantenimiento sin castigar ausencias <a class="header-anchor" href="#maintenance-without-absence-punishment" aria-label="Enlace permanente a &quot;Mantenimiento sin castigar ausencias&quot;">​</a></h2><p>Usar una ventana móvil de <strong>días activos</strong> en lugar de decaimiento basado solo en calendario real. La ausencia no debería castigar al jugador. El uso válido en el mundo mantiene fluidez; instalaciones dedicadas pueden hacerlo con menos repeticiones. Qué cuenta como día activo o uso válido sigue Sin resolver y debe impedir spam/macros triviales.</p><table tabindex="0"><thead><tr><th>Solo prototipo ilustrativo de mantenimiento</th><th>Candidato de uso en el mundo</th><th>Alternativa de entrenamiento dedicado</th></tr></thead><tbody><tr><td>Mastered</td><td>Unos 20 usos válidos en unos 7 días activos</td><td>Unas 5 repeticiones</td></tr><tr><td>Practiced</td><td>Unos 8–10 usos válidos; ventana precisa sin resolver</td><td>Unas 2–3 repeticiones</td></tr><tr><td>Learned</td><td>Ningún mantenimiento para conservar conocimiento</td><td>Nunca desaparece por decaimiento</td></tr></tbody></table><p>Estos recuentos ilustrativos de Batch 05 no son configuraciones de ejecución ni requisitos definitivos. La <a href="/Syrolands-Public/es/game-design/combat/numeric-prototype.html#maintenance-test">prueba acotada de Batch 06</a> elige ahora 9/3 para Practiced y una ventana de siete días activos para ambos niveles; fuera de esa prueba, las cuestiones más amplias siguen abiertas. La ventana de ejemplo de Mastered no debe convertirse silenciosamente en la ventana definitiva de Practiced. El avance a niveles superiores, definición de actividad, límites de evaluación, progreso parcial, controles de abuso y ritmo de decaimiento requieren pruebas. Las técnicas preparadas podrían decaer más lentamente que las no preparadas; no se selecciona ninguna regla.</p><h2 id="training-facilities-and-crafts" tabindex="-1">Instalaciones de entrenamiento y oficios <a class="header-anchor" href="#training-facilities-and-crafts" aria-label="Enlace permanente a &quot;Instalaciones de entrenamiento y oficios&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Instalación con estado Propuesto</th><th>Apoyo fabricado candidato</th></tr></thead><tbody><tr><td>Gimnasio marcial/sala de entrenamiento urbana</td><td>Training Dummy, Reinforced Combat Dummy, Articulated Limb Dummy</td></tr><tr><td>Academia de magos/círculo de práctica de hechizos</td><td>Foco de práctica mágica</td></tr><tr><td>Sala de entrenamiento de casa/gremio</td><td>Objetos y mecanismos de práctica adecuados</td></tr><tr><td>Área de entrenamiento a distancia</td><td>Moving Target, mecanismos de campo de tiro</td></tr></tbody></table><p>Carpentry, Tinkering e Inscription pueden contribuir; esto no asigna recetas finales ni crea habilidades nuevas. Las instalaciones mantienen Familiarity eficientemente y reducen tareas repetitivas. No deberían ser el ciclo óptimo de mejora de habilidades principales ni trivializar descubrimiento/dominio. Propiedad/acceso, validez de desafíos, seguridad y controles de automatización siguen abiertos.</p><h2 id="preparation-and-int" tabindex="-1">Preparación e INT <a class="header-anchor" href="#preparation-and-int" aria-label="Enlace permanente a &quot;Preparación e INT&quot;">​</a></h2><p><a href="/Syrolands-Public/es/game-design/combat/actions.html#learning-familiarity-and-prepared-options">Prepared Combat Repertoire</a> propone cinco ranuras de SA solo como prueba inicial de experiencia. INT no es un requisito fijo ni una inversión obligatoria para guerreros. <a href="/Syrolands-Public/es/game-design/magic/memory-and-familiarity.html">Active Memory</a> de hechizos conserva su propio modelo propuesto de complejidad cognitiva; no transferir cinco ranuras marciales a magia.</p><h2 id="open-questions" tabindex="-1">Preguntas abiertas <a class="header-anchor" href="#open-questions" aria-label="Enlace permanente a &quot;Preguntas abiertas&quot;">​</a></h2><p>Fuera de la <a href="/Syrolands-Public/es/game-design/combat/numeric-prototype.html#maintenance-test">prueba acotada de retención de Batch 06</a>, umbrales de entrada/mantenimiento/decaimiento de niveles, uso válido, definición de día activo, equivalencia de entrenamiento, ventaja de decaimiento por preparación, efectos por acción, respuesta de interfaz, resistencia a macros, accesibilidad y cómo interactúan fizzle/Concentration de hechizos con fluidez. Esto no cambia ganancia de habilidades, datos guardados ni técnicas aprendidas en ejecución.</p><h2 id="batch-06-numeric-test-scope" tabindex="-1">Alcance numérico de prueba de Batch 06 <a class="header-anchor" href="#batch-06-numeric-test-scope" aria-label="Enlace permanente a &quot;Alcance numérico de prueba de Batch 06&quot;">​</a></h2><p>El <a href="/Syrolands-Public/es/game-design/combat/numeric-prototype.html">perfil de tres armas</a> asigna valores de prueba con estado Experimental a Longsword, Spear y War Hammer. Sus reglas de fases, recursos, cadencia, Flow, Familiarity marcial y preparación solo se aplican a esa prueba futura. Los ejemplos anteriores siguen siendo alternativas históricas fuera de este perfil; de ello no se deriva equilibrio definitivo, implementación de juego ni asignación numérica de hechizos.</p>',21)])])}const h=a(r,[["render",o]]);export{u as __pageData,h as default};
